question:
What is printed by the following ANSI C program?

#include <stdio.h>
int main(int argc, char *argv[]) {
    int x = 1, z[2] = {10, 11};
    int *p = NULL;
    p = &x;
    *p = 10;
    p = &z[1];
    *(&z[0] + 1) += 3;
    printf("%d, %d, %d\n", x, z[0], z[1]);
    return 0;
}

What happens when the following C code executes?

int a = 6; int b = 0;
while (a < 10) {
    a = a / 12 + 1;
    a += b;
}

What is the output of the C program assuming function arguments evaluate from right to left?

#include <stdio.h>
int g(int p) { printf("%d", p); return p; }
int h(int q) { printf("%d", q); return q; }
void f(int x, int y) { g(x); h(y); }
int main() { f(g(10), h(20)); }

What is the output of the C program?

#include <stdio.h>
int main() {
    double a[2] = {20.0, 25.0}, *p, *q;
    p = a;
    q = p + 1;
    printf("%d,%d", (int)(q - p), (int)(*q - *p));
    return 0;
}

What is the output of the following C code segment?

int x=126, y=105;
do {
    if (x>y) x=x-y;
    else y=y-x;
} while (x!=y);
printf("%d", x);

What is the output of the following C program?
#include<stdio.h>
int fun(int n) {
if (n <= 1) return 1;
return fun(n/2) + fun(n/2) + 1;
}
int main() { printf("%d", fun(7)); return 0; }

